package org.slavicmyths.quest185;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.item.*;
import net.minecraft.network.chat.*;
import org.slavicmyths.poloz.PolozContent;
import org.slavicmyths.rpg.Runes;
import org.slavicmyths.yaga.*;
import org.slavicmyths.tales.*;
public final class Quest185Story {
 public static CompoundTag data(net.minecraft.world.entity.player.Player p){var root=org.slavicmyths.rpg.PathData.data(p);if(!root.contains("Quest185",10))root.put("Quest185",new CompoundTag());var n=root.getCompound("Quest185");n.putInt("Version",2);return n;}
 public static long now(ServerPlayer p){return p.server.overworld().getGameTime();}
 public static Component text(String s,Object...args){return Component.translatable("quest185."+s,args);}
 public static int wolfTrust(ServerPlayer p){if(!org.slavicmyths.wolf.WolfProgress.passed(p))return 1;return oldWolfDone(p)?(Quest185State.done(data(p),8)?4:3):2;}
 public static boolean oldWolfDone(ServerPlayer p){return org.slavicmyths.military.MilitaryQuests.state(p).getCompound("GreyWolfStory").getCompound(org.slavicmyths.military.GreyWolfStory.IDS[3]).getBoolean("Claimed");}
 public static boolean metYaga(ServerPlayer p){return data(p).getBoolean("MetYaga")||YagaData.get(p.server.overworld()).progress(p.getUUID()).intro>=2;}
 public static int yagaTrust(ServerPlayer p){return YagaData.get(p.server.overworld()).progress(p.getUUID()).stage>=3?3:YagaData.get(p.server.overworld()).progress(p.getUUID()).stage>=1?2:1;}
 public static boolean metBayun(ServerPlayer p){return data(p).getBoolean("MetBayun");}
 public static int bayunTrust(ServerPlayer p){var n=data(p);if(!n.hasUUID("Bayun"))return 0;var bonds=TaleData.get(p.server.overworld()).player(p.getUUID()).getCompound("Bonds").getCompound(n.getUUID("Bayun").toString());int trust=bonds.getInt("Trust");return trust>=85?3:bonds.getBoolean("FirstGift")?2:1;}
 public static void talk(ServerPlayer p,Entity npc){var n=data(p);if(npc instanceof BabaYaga y){n.putBoolean("MetYaga",true);n.putLong("YagaDialogAt",now(p));var world=YagaData.get(p.serverLevel());if(world.placed&&world.anchor!=null&&world.npc!=null&&world.npc.equals(y.getUUID())){n.putLong("Hut",world.anchor.asLong());n.putString("HutDimension",p.level().dimension().location().toString());}}else if(npc instanceof org.slavicmyths.bayun.BayunEntity b){n.putBoolean("MetBayun",true);n.putUUID("Bayun",b.getUUID());n.putLong("BayunDialogAt",now(p));}else if(npc instanceof org.slavicmyths.wolf.GreyWolf){n.putBoolean("MetWolf",true);}migrate(p);invite(p);}
 public static void migrate(ServerPlayer p){var n=data(p);if(!n.getBoolean("FinalMigrationChecked")){n.putBoolean("LegacyEyeProof",Runes.inventoryCount(p,PolozContent.EYE.get())>0);if(n.getBoolean("Cleansing")&&Quest185State.done(n,5))n.putBoolean("LikhoResearchRewardClaimed",true);n.putBoolean("FinalMigrationChecked",true);}if(Runes.inventoryCount(p,PolozContent.HORN.get())>0){n.putBoolean("Horn",true);if(!n.getBoolean("MigrationChecked"))n.putBoolean("LegacyHornProof",true);}n.putBoolean("MigrationChecked",true);if(org.slavicmyths.progression.Knowledge.knows(p,"great_poloz_fall"))n.putBoolean("Poloz",true);if(metYaga(p)&&!n.contains("Hut")){var d=YagaData.get(p.server.overworld());if(d.placed&&d.anchor!=null){n.putLong("Hut",d.anchor.asLong());n.putString("HutDimension","minecraft:overworld");}}
 }
 public static void invite(ServerPlayer p){var n=data(p);if(n.getInt("MorKills")<=0||n.getBoolean("Invitation")||n.getBoolean("IntroDone"))return;String speaker=Quest185State.inviter(metYaga(p),metBayun(p),n.getLong("YagaDialogAt"),n.getLong("BayunDialogAt"));if(speaker.isEmpty())return;n.putBoolean("Invitation",true);org.slavicmyths.progression.AdvancementJourney.award(p,"mor_invitation");n.putString("Inviter",speaker);if(!n.contains("Hut")){var hut=YagaData.get(p.server.overworld());if(hut.placed&&hut.anchor!=null){n.putLong("Hut",hut.anchor.asLong());n.putString("HutDimension","minecraft:overworld");}}p.sendSystemMessage(text("invite."+speaker));Quest185Sessions.invitation(p,speaker);Quest185Content.sound(p,"invitation");TaleService.promote(p,"slavicmyths:mor_investigation",2,false);}
 public static boolean trophies(ServerPlayer p){return Runes.inventoryCount(p,PolozContent.EYE.get())>0&&Runes.inventoryCount(p,PolozContent.HEART.get())>0;}
 public static Quest185State.Status status(ServerPlayer p,int i){migrate(p);return Quest185State.status(data(p),i,Runes.inventoryCount(p,PolozContent.DUST.get()),trophies(p),wolfTrust(p),oldWolfDone(p));}
 public static boolean spend(ServerPlayer p,Item item,int count){if(Runes.inventoryCount(p,item)<count)return false;for(int i=0;i<p.getInventory().getContainerSize()&&count>0;i++){var s=p.getInventory().getItem(i);if(s.is(item)){int take=Math.min(count,s.getCount());s.shrink(take);count-=take;}}p.getInventory().setChanged();return true;}
 public static ItemStack reward(int i){return switch(i){case 0,7->new ItemStack(Quest185Content.WARD.get());case 2->new ItemStack(Quest185Content.TRACKER.get());case 5->ItemStack.EMPTY;case 6->new ItemStack(PolozContent.DUST.get(),3);case 8->new ItemStack(Quest185Content.CALL.get());default->ItemStack.EMPTY;};}
 public static boolean claim(ServerPlayer p,int i){if(i<0||i>=9||status(p,i)!=Quest185State.Status.READY)return false;var n=data(p);if(i==1&&!spend(p,PolozContent.DUST.get(),3))return false;if(i==2&&trophies(p)){n.putBoolean("EyeShown",true);n.putBoolean("TrophiesVerified",true);}if(!Quest185State.claim(n,i))return false;
  var reward=reward(i);if(!reward.isEmpty())Quest185State.quest(n,i).put("Pending",reward.save(p.registryAccess()));p.giveExperiencePoints(Quest185State.XP[i]);collect(p);if(i==1){n.putBoolean("UtilityRecipes",true);discover(p,"mor_ward","tracker_sense");}if(i==2||i==3)discover(p,"mor_horn");if(i==5){n.putBoolean("FinalChapter",true);org.slavicmyths.progression.AdvancementJourney.award(p,"mor_story_complete");TaleService.promote(p,"slavicmyths:mor_investigation",4,true);}if(i==8)n.putBoolean("WolfUnlocked",true);TaleService.promote(p,"slavicmyths:mor_investigation",3,false);Quest185Content.sound(p,"quest_claim");return true;
 }
 public static void discover(ServerPlayer p,String...ids){p.awardRecipesByKey(Arrays.stream(ids).map(Quest185Content::id).toList());}
 public static void collect(ServerPlayer p){var n=data(p);for(int i=0;i<9;i++){var q=Quest185State.quest(n,i);if(!q.contains("Pending",10))continue;var item=ItemStack.parseOptional(p.registryAccess(),q.getCompound("Pending"));p.getInventory().add(item);if(item.isEmpty())q.remove("Pending");else q.put("Pending",item.save(p.registryAccess()));}for(String key:List.of("EarlyPending","EarthPending")){if(!n.contains(key,10))continue;var item=ItemStack.parseOptional(p.registryAccess(),n.getCompound(key));p.getInventory().add(item);if(item.isEmpty())n.remove(key);else n.put(key,item.save(p.registryAccess()));}p.getInventory().setChanged();}
 public static CompoundTag snapshot(ServerPlayer p){migrate(p);var n=data(p);var out=new CompoundTag();out.putBoolean("IntroDone",n.getBoolean("IntroDone"));out.putBoolean("Invitation",n.getBoolean("Invitation"));out.putBoolean("Cleansing",n.getBoolean("Cleansing"));out.putBoolean("EyeReady",eyeReady(p));out.putBoolean("EarthClaimed",n.getBoolean("EarthRestorationRewardClaimed"));out.putInt("EarthCount",CleansingLessons.get(p.serverLevel()).count(p.getUUID()));out.putBoolean("EarthVirtual",CleansingLessons.get(p.serverLevel()).virtual(p.getUUID()));out.putBoolean("HutKnown",n.contains("Hut"));if(n.contains("Hut"))out.putLong("Hut",n.getLong("Hut"));out.putInt("Kills",n.getInt("MorKills"));out.putInt("Dust",Runes.inventoryCount(p,PolozContent.DUST.get()));out.putBoolean("Likho",n.getBoolean("Likho"));out.putBoolean("Ovinnik",n.getBoolean("Ovinnik"));out.putBoolean("Poloz",n.getBoolean("Poloz"));var stages=new ListTag();for(int i=0;i<9;i++){var q=new CompoundTag();q.putString("Id",Quest185State.IDS[i]);q.putString("Status",status(p,i).name());q.putBoolean("Pending",Quest185State.quest(n,i).contains("Pending"));q.putInt("Progress",i==0?n.getInt("MorKills"):i==1?Runes.inventoryCount(p,PolozContent.DUST.get()):i==7?n.getInt("BasicKills")-Quest185State.quest(n,i).getInt("StartKills"):i==8?Quest185State.quest(n,i).getInt("TrainingKills"):0);stages.add(q);}out.put("Stages",stages);out.putInt("WolfTrust",wolfTrust(p));return out;}
 public static boolean eyeReady(ServerPlayer p){var n=data(p);return Quest185State.earlyReady(n,Runes.inventoryCount(p,PolozContent.EYE.get())>0);}
 public static boolean researchEye(ServerPlayer p){var n=data(p);if(!Quest185State.claimEarly(n,Runes.inventoryCount(p,PolozContent.EYE.get())>0))return false;n.put("EarlyPending",new ItemStack(Quest185Content.POWDER.get(),4).save(p.registryAccess()));discover(p,"cleansing_powder");TaleService.promote(p,"slavicmyths:cleansing_knowledge",4,true);collect(p);return true;}
 public static boolean claimEarth(ServerPlayer p){var n=data(p);if(!Quest185State.claimEarth(n,CleansingLessons.get(p.serverLevel()).count(p.getUUID())))return false;n.put("EarthPending",new ItemStack(Quest185Content.POWDER.get(),8).save(p.registryAccess()));p.giveExperiencePoints(175);CleansingLessons.get(p.serverLevel()).finish(p);collect(p);Quest185Content.sound(p,"quest_claim");return true;}
 private Quest185Story(){}
}
